template<class D, class T>
void validate_result(D* device_result, const T* cpu_reference, const char* name, std::size_t num_elements, T tolerance=1e-4) {
    D* out_gpu = (D*)malloc(num_elements * sizeof(D));
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_in_order_queue()
            .memcpy(out_gpu, device_result, num_elements * sizeof(D))
            .wait()));
    int nfaults = 0;
#ifndef ENABLE_BF16
    float epsilon = FLT_EPSILON;
#else
    float epsilon = 0.079;
#endif
    for (int i = 0; i < num_elements; i++) {
        // Skip masked elements
        if(!isfinite(cpu_reference[i]))
            continue;

        // print the first few comparisons
        if (i < 5) {
            printf("%f %f\n", cpu_reference[i], (T)out_gpu[i]);
        }
        // effective tolerance is based on expected rounding error (epsilon),
        // plus any specified additional tolerance
        float t_eff = tolerance + fabs(cpu_reference[i]) * epsilon;
        // ensure correctness for all elements.
        if (fabs(cpu_reference[i] - (T)out_gpu[i]) > t_eff) {
            printf("Mismatch of %s at %d: CPU_ref: %f vs GPU: %f\n", name, i, cpu_reference[i], (T)out_gpu[i]);
            nfaults ++;
            if (nfaults >= 10) {
                free(out_gpu);
                exit(EXIT_FAILURE);
            }
        }
    }

    if (nfaults > 0) {
        free(out_gpu);
        exit(EXIT_FAILURE);
    }

    free(out_gpu);
}

template<class Kernel, class... KernelArgs>
float benchmark_kernel(int repeats, Kernel kernel, KernelArgs&&... kernel_args) {
    dpct::event_ptr start, stop;
    // prepare buffer to scrub L2 cache between benchmarks
    // just memset a large dummy array, recommended by
    // https://stackoverflow.com/questions/31429377/how-can-i-clear-flush-the-l2-cache-and-the-tlb-of-a-gpu
    // and apparently used in nvbench.
    int deviceIdx = 0;
    /*
    DPCT1093:22: The "deviceIdx" device may be not the one intended for use.
    Adjust the selected device if needed.
    */
    cudaCheck(DPCT_CHECK_ERROR(dpct::select_device(deviceIdx)));
    dpct::device_info deviceProp;
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_device(deviceIdx).get_device_info(deviceProp)));
    void* flush_buffer;
    /*
    DPCT1051:23: SYCL does not support a device property functionally compatible
    with l2CacheSize. It was migrated to global_mem_cache_size. You may need to
    adjust the value of global_mem_cache_size for the specific device.
    */
    cudaCheck(DPCT_CHECK_ERROR(flush_buffer = (void *)sycl::malloc_device(
                                   deviceProp.get_global_mem_cache_size(),
                                   dpct::get_in_order_queue())));

    cudaCheck(DPCT_CHECK_ERROR(start = new sycl::event()));
    cudaCheck(DPCT_CHECK_ERROR(stop = new sycl::event()));
    float elapsed_time = 0.f;
    for (int i = 0; i < repeats; i++) {
        // clear L2
        /*
        DPCT1051:24: SYCL does not support a device property functionally
        compatible with l2CacheSize. It was migrated to global_mem_cache_size.
        You may need to adjust the value of global_mem_cache_size for the
        specific device.
        */
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memset(flush_buffer, 0, deviceProp.get_global_mem_cache_size())
                .wait()));
        // now we can start recording the timing of the kernel
        /*
        DPCT1024:25: The original code returned the error code that was further
        consumed by the program logic. This original code was replaced with 0.
        You may need to rewrite the program logic consuming the error code.
        */
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::sync_barrier(start, &dpct::get_in_order_queue())));
        kernel(std::forward<KernelArgs>(kernel_args)...);
        /*
        DPCT1024:26: The original code returned the error code that was further
        consumed by the program logic. This original code was replaced with 0.
        You may need to rewrite the program logic consuming the error code.
        */
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::sync_barrier(stop, &dpct::get_in_order_queue())));
        cudaCheck(DPCT_CHECK_ERROR(start->wait_and_throw()));
        cudaCheck(DPCT_CHECK_ERROR(stop->wait_and_throw()));
        float single_call;
        cudaCheck(DPCT_CHECK_ERROR(
            single_call = (stop->get_profiling_info<
                               sycl::info::event_profiling::command_end>() -
                           start->get_profiling_info<
                               sycl::info::event_profiling::command_start>()) /
                          1000000.0f));
        elapsed_time += single_call;
    }

    cudaCheck(DPCT_CHECK_ERROR(
        dpct::dpct_free(flush_buffer, dpct::get_in_order_queue())));

    return elapsed_time / repeats;
}

/*
Kernels for layernorm forward pass.

Compile example:
nvcc -O3 --use_fast_math -lcublas -lcublasLt layernorm_forward.cu -o layernorm_forward

version 1 is naive port from CPU code to kernel: parallelizes over B,T, loops over C
./layernorm_forward 1

version 2 parallelizes over all of B,T,C
./layernorm_forward 2

version 3 uses cooperative groups to parallelize over all of B,T,C
./layernorm_forward 3

version 4 uses a more clever way to estimate variance, var(x) = mean(x**2) - mean(x)**2
          (allowing us to do a single pass over x on load)
./layernorm_forward 4

verstion 5 allocates blocks per row instead of warps per row, same alg as 4 otherwise
./layernorm_forward 5
*/

#define DPCT_PROFILING_ENABLED
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include "common.h"
// ----------------------------------------------------------------------------
// CPU code reference

// GPT-2 layernorm forward pass
// museport: CPU reference layernorm_forward_cpu() removed (it is the hidden check)

// ----------------------------------------------------------------------------
// GPU kernels

// naive drag and drop implementation into kernel, parallelize over B,T, loop over C
void layernorm_forward_kernel1(float* out, float* mean, float* rstd,
                                 const float* inp, const float* weight, const float* bias,
                                 int N, int C) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
              item_ct1.get_local_id(2);
    float eps = 1e-5f;

    if (idx < N) {
        // seek to the input position inp[idx,:]
        const float* x = inp + idx * C;
        // calculate the mean
        float m = 0.0f;
        for (int i = 0; i < C; i++) {
            m += x[i];
        }
        m = m / C;
        // calculate the variance (without any bias correction)
        float v = 0.0f;
        for (int i = 0; i < C; i++) {
            float xshift = x[i] - m;
            v += xshift * xshift;
        }
        v = v / C;
        // calculate the rstd
        float s = 1.0f / sycl::sqrt(v + eps);
        // seek to the output position in out[idx,:]
        float* out_idx = out + idx * C;
        for (int i = 0; i < C; i++) {
            float n = (s * (x[i] - m)); // normalized output
            float o = n * weight[i] + bias[i]; // scale and shift it
            out_idx[i] = o; // write
        }
        // cache the mean and rstd for the backward pass later
        mean[idx] = m;
        rstd[idx] = s;
    }
}

void mean_kernel(float* mean, const float* inp, int N, int C, int block_size,
                 uint8_t *dpct_local) {
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    auto shared = (float *)dpct_local;
    int idx = item_ct1.get_group(2);    // range [0, B*T)
    int tid = item_ct1.get_local_id(2); // range [0, block_size)
