                       float block_sum = sycl::reduce_over_group(grp, thread_sum, sycl::plus<float>{});
                       float block_sum2 = sycl::reduce_over_group(grp, thread_sum2, sycl::plus<float>{});
                       block_sum /= static_cast<float>(C);
